/* -----------------------------------------------------------------------
 * display_logic.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: Tony; Brendon (integrator) added ui_effect_name() (Sep 2026), the 28 Oct 2026 demo screens (speaker lockout, battery time, fault, debug) and the Play screen's Preparing and n/a lines (29-30 Oct 2026, with an AI coding assistant).
 * BJT2 Sound Modulating Toy — Display Logic Implementation
 * Author: Tony (Display/UI subsystem)
 *
 * Turns the UI state (ui_state_t) into the words each screen shows
 * (display_info_t: up to six info lines; only the Battery screen uses
 * lines 5 and 6), plus the small text helpers
 * the screens and the footer share (effect names, hh:mm, "Insert SD
 * card"). It only builds text: no SPI, no HAL. See display_logic.h for
 * what each function returns.
 *
 * No task of its own: tony_ui.c calls ui_get_display_info() inside
 * TonyTask on every loop pass, then draws only the lines whose text
 * changed.
 * ----------------------------------------------------------------------- */

#include "display_logic.h"
#include "ui_state_machine.h"
#include <string.h>
#include <stdio.h>

/* Effect labels: Tom's effect names in UI order (EFFECT_1..6). */
static const char *const effect_names[EFFECT_COUNT] = {
    "None",        /* EFFECT_NONE */
    "Autotune",    /* EFFECT_1 */
    "Pitch Up",    /* EFFECT_2 */
    "Pitch Down",  /* EFFECT_3 */
    "Robot",       /* EFFECT_4 */
    "Echo",        /* EFFECT_5 */
    "Reverb",      /* EFFECT_6 */
};

const char *ui_effect_name(ui_effect_t e)
{
    if ((int)e < 0 || e >= EFFECT_COUNT) {
        return "?";
    }
    return effect_names[e];
}

/* Fault screen line 1: where the fault came from (ui_fault_source_t order). */
static const char *const fault_source_names[UI_FAULT_SRC_COUNT] = {
    "Storage",     /* UI_FAULT_SRC_STORAGE */
    "Battery",     /* UI_FAULT_SRC_BATTERY */
    "USB",         /* UI_FAULT_SRC_USB */
    "Audio",       /* UI_FAULT_SRC_AUDIO */
    "System",      /* UI_FAULT_SRC_SYSTEM */
};

const char *ui_fault_source_name(uint8_t source)
{
    if (source >= (uint8_t)UI_FAULT_SRC_COUNT) {
        return "Unknown";
    }
    return fault_source_names[source];
}

/* -----------------------------------------------------------------------
 * battery_mv_to_pct
 * Linear map from [BATTERY_MV_MIN, BATTERY_MV_MAX] to [0, 100].
 * Uses uint32_t intermediate to prevent overflow during multiplication.
 * Kept and host-tested, but the firmware no longer calls it: the battery
 * % on the screen is the fuel gauge's own SoC (state of charge) from
 * Brendon's battery message (BatteryMsg_t.soc_pct).
 * ----------------------------------------------------------------------- */
uint8_t battery_mv_to_pct(uint16_t mv)
{
    if (mv <= BATTERY_MV_MIN) {
        return 0U;
    }
    if (mv >= BATTERY_MV_MAX) {
        return 100U;
    }
    uint32_t range = BATTERY_MV_MAX - BATTERY_MV_MIN;
    uint32_t pct   = ((uint32_t)(mv - BATTERY_MV_MIN) * 100U) / range;
    return (uint8_t)pct;
}

/* -----------------------------------------------------------------------
 * ui_format_hhmm
 * Minutes -> "hh:mm". The gauge's "no estimate" becomes "--:--", and
 * anything past 99:59 is clamped so the text is always 5 characters.
 * ----------------------------------------------------------------------- */
#define HHMM_MAX_MIN    5999U   /* 99 h 59 min: the most two hour digits show */

void ui_format_hhmm(uint16_t minutes, char *out, size_t len)
{
    if (out == NULL || len == 0U) {
        return;
    }
    if (minutes == UI_TIME_UNKNOWN) {
        snprintf(out, len, "--:--");
        return;
    }
    if (minutes > HHMM_MAX_MIN) {
        minutes = HHMM_MAX_MIN;
    }
    snprintf(out, len, "%02u:%02u",
             (unsigned)(minutes / 60U), (unsigned)(minutes % 60U));
}

const char *ui_battery_time_label(bool charging)
{
    return charging ? "To full" : "Time left";
}

/* -----------------------------------------------------------------------
 * ui_record_start_label / ui_play_idle_name
 * With no card in the slot (Jack's newest status) the Record and Play
 * screens say what to do instead of offering what cannot work. Before
 * Jack's first status sd_status is still SD_STATUS_OK (ui_init): REC and
 * PLAY are offered and Jack decides.
 * ----------------------------------------------------------------------- */
const char *ui_record_start_label(const ui_state_t *s)
{
    if (s != NULL && s->sd_status == SD_STATUS_NO_CARD) {
        return UI_TEXT_INSERT_CARD;
    }
    return "Start Recording";
}

const char *ui_play_idle_name(const ui_state_t *s, const char *selected)
{
    if (s == NULL) {
        return "";
    }
    if (s->sd_status == SD_STATUS_NO_CARD) {
        return UI_TEXT_INSERT_CARD;
    }
    if (s->file_count == 0U) {
        return "No recordings";
    }
    return (selected != NULL) ? selected : "";
}

/* -----------------------------------------------------------------------
 * ui_is_preparing
 * The UI is playing and Jack is still making the effect file that PLAY
 * waits for (prep_pct holds his percentage).
 * ----------------------------------------------------------------------- */
bool ui_is_preparing(const ui_state_t *s)
{
    return (s != NULL) && s->playback == PLAYBACK_PLAYING && s->prep_pct != UI_PREP_NONE;
}

/* -----------------------------------------------------------------------
 * ui_rows_changed
 * The old and new cursor rows when the cursor moved, plus the old and
 * new active rows when the active effect changed. A row index the 8-bit
 * mask cannot hold (UI_ROW_NONE included) adds nothing.
 * ----------------------------------------------------------------------- */
static uint8_t row_bit(uint8_t row)
{
    return (row < 8U) ? (uint8_t)(1U << row) : 0U;
}

uint8_t ui_rows_changed(uint8_t prev_hi, uint8_t now_hi,
                        uint8_t prev_active, uint8_t now_active)
{
    uint8_t mask = 0U;
    if (prev_hi != now_hi) {
        mask |= (uint8_t)(row_bit(prev_hi) | row_bit(now_hi));
    }
    if (prev_active != now_active) {
        mask |= (uint8_t)(row_bit(prev_active) | row_bit(now_active));
    }
    return mask;
}

/* -----------------------------------------------------------------------
 * ui_find_file
 * A straight search: the list is short (Jack sends at most 16 names).
 * strncmp stops after DISPLAY_FILE_MAX bytes, the size of one entry.
 * ----------------------------------------------------------------------- */
uint8_t ui_find_file(const char names[][DISPLAY_FILE_MAX], uint8_t count,
                     const char *name)
{
    if (names == NULL || name == NULL || name[0] == '\0') {
        return count;
    }
    for (uint8_t i = 0U; i < count; i++) {
        if (strncmp(names[i], name, DISPLAY_FILE_MAX) == 0) {
            return i;
        }
    }
    return count;
}

/* -----------------------------------------------------------------------
 * ui_get_display_info
 * Translates ui_state_t into a display_info_t that the display driver
 * reads to decide what to draw. No HAL or SPI calls here.
 * ----------------------------------------------------------------------- */
void ui_get_display_info(const ui_state_t *s, display_info_t *out)
{
    if (s == NULL || out == NULL) {
        return;
    }

    /* Clear the output struct first */
    memset(out, 0, sizeof(display_info_t));

    /* Persistent status bar items — shown on every screen */
    out->screen           = s->screen;
    out->battery_pct      = s->battery_pct;
    out->muted            = s->muted;
    out->autotune_on      = (s->active_effect != EFFECT_NONE);
    out->effective_volume = ui_get_effective_volume(s);
    out->battery_mv       = s->battery_mv;
    out->home_highlighted = s->home_highlighted;

    /* Per-screen content */
    switch (s->screen) {

        case UI_SCREEN_HOME:
            /* The menu rows already name every item: no info lines here
             * (they used to repeat "Record / Play / Volume" beside them). */
            break;

        case UI_SCREEN_RECORD:
            if (s->playback == PLAYBACK_RECORDING) {
                snprintf(out->line1, DISPLAY_LABEL_MAX, "Recording...");
                snprintf(out->line2, DISPLAY_LABEL_MAX, "Stop");
            } else {
                /* "Insert SD card" while the slot is empty, as the start row */
                snprintf(out->line1, DISPLAY_LABEL_MAX, "%s", ui_record_start_label(s));
                out->line2[0] = '\0';
            }
            break;

        case UI_SCREEN_PLAY:
            if (ui_is_preparing(s)) {
                /* The effect file is being made first; it plays by itself
                 * when done. Widest: "Preparing 100%" = 14 characters. */
                snprintf(out->line1, DISPLAY_LABEL_MAX, "Preparing %u%%", (unsigned)s->prep_pct);
            } else if (s->playback == PLAYBACK_PLAYING) {
                snprintf(out->line1, DISPLAY_LABEL_MAX, "Playing (loop)");
            } else if (s->playback == PLAYBACK_PAUSED) {
                snprintf(out->line1, DISPLAY_LABEL_MAX, "Paused");
            } else {
                snprintf(out->line1, DISPLAY_LABEL_MAX, "Stopped");
            }
            if (s->fx_na) {
                /* The original plays although an effect is selected (this
                 * file cannot have it): 18 characters. */
                snprintf(out->line2, DISPLAY_LABEL_MAX, "Effect: None (n/a)");
            } else if (s->active_effect == EFFECT_NONE) {
                snprintf(out->line2, DISPLAY_LABEL_MAX, "Effect: None");
            } else {
                snprintf(out->line2, DISPLAY_LABEL_MAX,
                         "Effect: %s", ui_effect_name(s->active_effect));
            }
            if (s->speaker_locked) {
                /* Battery lockout: show the stored level (the encoder still
                 * changes it) and say why nothing is heard. The speaker is
                 * silent whatever the mute setting, so "(locked)" replaces
                 * "(Muted)". Widest: "Vol: 100 (locked)" = 17 chars. */
                snprintf(out->line3, DISPLAY_LABEL_MAX,
                         "Vol: %u (locked)", s->volume);
            } else {
                snprintf(out->line3, DISPLAY_LABEL_MAX,
                         "Vol: %u%s", out->effective_volume,
                         s->muted ? " (Muted)" : "");
            }
            break;

        case UI_SCREEN_EFFECTS:
            if (s->active_effect == EFFECT_NONE) {
                snprintf(out->line1, DISPLAY_LABEL_MAX, "Active: None");
            } else {
                snprintf(out->line1, DISPLAY_LABEL_MAX,
                         "Active: %s", ui_effect_name(s->active_effect));
            }
            snprintf(out->line2, DISPLAY_LABEL_MAX,
                     "Cursor: %s", ui_effect_name(s->effect_highlighted));
            if (s->active_effect == s->effect_highlighted) {
                snprintf(out->line3, DISPLAY_LABEL_MAX, "[ON] Tap to turn off");
            } else {
                snprintf(out->line3, DISPLAY_LABEL_MAX, "[OFF] Tap to activate");
            }
            break;

        case UI_SCREEN_VOLUME:
            if (s->speaker_locked) {
                /* Battery lockout: -/+ and the encoder still store the
                 * level, marked as locked. Widest line1:
                 * "Volume: 100 (locked)" = 20 chars, the size-2 limit. */
                snprintf(out->line1, DISPLAY_LABEL_MAX,
                         "Volume: %u (locked)", s->volume);
                snprintf(out->line2, DISPLAY_LABEL_MAX, "Low battery");
            } else {
                snprintf(out->line1, DISPLAY_LABEL_MAX,
                         "Volume: %u", s->volume);
                snprintf(out->line2, DISPLAY_LABEL_MAX,
                         s->muted ? "MUTED" : "");
            }
            break;

        case UI_SCREEN_FILE:
            if (s->file_count == 0U) {
                snprintf(out->line1, DISPLAY_LABEL_MAX, "No files found");
            } else {
                /* Widest: "File 65535 of 65535" = 19 characters */
                snprintf(out->line1, DISPLAY_LABEL_MAX,
                         "File %u of %u", (unsigned)s->file_index + 1U,
                         (unsigned)s->file_count);
            }
            snprintf(out->line2, DISPLAY_LABEL_MAX,
                     s->sd_status == SD_STATUS_OK ? "SD OK" : "SD Error");
            break;

        case UI_SCREEN_BATTERY: {
            /* Six lines, each value padded to its widest so the centred
             * text never shifts sideways when a digit changes:
             *   "Charge  80%"          (11 chars)
             *   "Current   -152 mA"    (17, also for -32768)
             *   "Average   -140 mA"    (17, also for -32768)
             *   "Voltage  3.712 V"     (16, also for 65.535)
             *   "Time left 01:15" or "To full   01:15"   (15)
             *   "Status Discharging "  (19: status padded to 12)
             * All within the 20-character limit of a size-2 line. Voltage
             * is the battery's voltage.
             * TEAM CODE (written by Brendon, 30 Oct and 1 Nov 2026):
             * Current is the gauge's current over the last second and
             * Average the current over the last 2 minutes (minus = the
             * battery is discharging). Music makes the current of each
             * second jump (about 125 mA idle, up to 400 mA for loud
             * music), so both are shown: the one that moves with the
             * sound and the steady one Brendon's times come from. The
             * time is the time to full while
             * charging, except when the battery drains on the charger
             * (loud music can take more than the charger gives): then
             * Brendon sends a time to empty, and that is shown. */
            char        hhmm[6];
            const char *status;
            bool        to_full = s->battery_charging &&
                                  s->battery_tte_min == UI_TIME_UNKNOWN;
            uint16_t    minutes = to_full ? s->battery_ttf_min
                                          : s->battery_tte_min;

            ui_format_hhmm(minutes, hhmm, sizeof(hhmm));

            /* Most important first: the lockout explains a silent speaker
             * ("Status Locked (low bat)" would be 23 characters, too wide
             * for one line, hence "Locked (low)"); then a missing gauge,
             * because without a valid reading the lines above are not
             * live data. "Full" is a time to full of 0; "Plugged in" is
             * on the charger but draining (a time to empty while
             * charging). */
            if (s->speaker_locked) {
                status = "Locked (low)";
            } else if (!s->battery_valid) {
                status = "No gauge";
            } else if (s->battery_ttf_min == 0U) {
                status = "Full";
            } else if (s->battery_charging && !to_full) {
                status = "Plugged in";
            } else if (s->battery_charging) {
                status = "Charging";
            } else {
                status = "Discharging";
            }

            snprintf(out->line1, DISPLAY_LABEL_MAX, "Charge %3u%%",
                     (unsigned)s->battery_pct);
            snprintf(out->line2, DISPLAY_LABEL_MAX, "Current %+6d mA",
                     (int)s->battery_ma_now);
            snprintf(out->line3, DISPLAY_LABEL_MAX, "Average %+6d mA",
                     (int)s->battery_ma_avg);
            snprintf(out->line4, DISPLAY_LABEL_MAX, "Voltage %2u.%03u V",   /* millivolts as volts */
                     (unsigned)(s->battery_mv / 1000U), (unsigned)(s->battery_mv % 1000U));
            snprintf(out->line5, DISPLAY_LABEL_MAX, "%-10s%s",
                     ui_battery_time_label(to_full), hhmm);
            snprintf(out->line6, DISPLAY_LABEL_MAX, "Status %-12s", status);
            break;
        }

        case UI_SCREEN_FAULT:
            /* Where it came from, what happened, what it means, how to
             * leave. Widest line1: "Unknown (simulated)" = 19 chars; the
             * fault text is already cut to 20 by ui_show_fault(). */
            snprintf(out->line1, DISPLAY_LABEL_MAX, "%s%s",
                     ui_fault_source_name(s->fault_source),
                     (s->fault_code & UI_FAULT_CODE_SIMULATED) ? " (simulated)" : "");
            snprintf(out->line2, DISPLAY_LABEL_MAX, "%s", s->fault_line2);
            snprintf(out->line3, DISPLAY_LABEL_MAX, "%s", s->fault_line3);
            snprintf(out->line4, DISPLAY_LABEL_MAX, "Press any key");
            break;

        case UI_SCREEN_DEBUG:
            /* No info lines: the firmware's debug renderer
             * (Core/Src/tony_debug.c) draws its own small-text pages. */
            break;

        default:
            break;
    }
}
